css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .recuerda{border: 2px solid var(--bosque); border-radius: 10px; padding: 8px 12px; margin-bottom: 11px;}
.mz .recuerda-titulo{font-size: 13px; font-weight: 700; font-family: sans-serif; margin-bottom: 5px;}
.mz .recuerda-cuerpo{font-size: 16px; line-height: 1.7;}
.mz .recuerda-cuerpo b{font-size: 18px;}
.mz .equiv-grid{display: grid; grid-template-columns: 1fr 1fr; gap: 8px 30px;}
.mz .equiv-fila{display: flex; align-items: center; gap: 8px; font-size: 16px; font-weight: 700;}
.mz .equiv-fila .pieza{white-space: nowrap;}
.mz .equiv-fila .caja-eq{width: 56px; height: 32px; border: 1.5px solid var(--bosque); border-radius: 6px; flex-shrink: 0;}
.mz .op-tabla{border-collapse: collapse;}
.mz .op-tabla th,.mz .op-tabla td{border: 1.5px solid var(--bosque); text-align: center;}
.mz .op-tabla th{font-family: sans-serif; font-size: 12px; background: #f3f3f3; padding: 3px 0; width: 95px;}
.mz .op-tabla td{height: 34px; font-size: 19px; font-weight: 700;}
.mz .op-tabla td.op-dado{background: #f3f3f3;}
.mz .valor-fila{display: flex; align-items: center; gap: 10px; font-size: 16px; font-weight: 600; margin-bottom: 9px; flex-wrap: wrap;}
.mz .valor-fila .num-marcado{font-size: 22px; font-weight: 700; letter-spacing: 2px;}
.mz .valor-fila .num-marcado .destacado{text-decoration: underline; text-underline-offset: 3px;}
.mz .valor-fila .caja-vale{width: 88px; height: 34px; border: 1.5px solid var(--bosque); border-radius: 6px;}
